import React, { useCallback, useEffect, useState } from 'react';

import ComboBox from '@splunk/react-ui/ComboBox';
import useFetchOptions from '@splunk/react-ui/fixtures/useFetchOptions';
import { _ } from '@splunk/ui-utils/i18n';

function Fetching() {
    /**
     * useFetchOptions mimics a real server by setting a timeout before returning new options and
     * also does filtering of options.
     */
    const { fetch, getFullCount, stop } = useFetchOptions();

    const [fullCount, setFullCount] = useState(0);
    const [isLoading, setIsLoading] = useState(false);
    const [options, setOptions] = useState([]);
    const [value, setValue] = useState('');

    const handleFetch = useCallback(
        (comboBoxValue = '') => {
            setValue(comboBoxValue);
            setIsLoading(true);
            fetch(comboBoxValue)
                .then((comboBoxOptions) => {
                    setFullCount(getFullCount());
                    setIsLoading(false);
                    setOptions(comboBoxOptions);
                })
                .catch((error) => {
                    if (!error.isCanceled) {
                        throw error;
                    }
                });
        },
        [fetch, getFullCount]
    );

    const generateOptions = () => {
        if (isLoading) {
            return null;
        }

        /*
         * Filtering is done server-side and the `matchRanges` prop would be either
         * be provided by the server, deduced based on the match algorithm, or omitted.
         */
        return options.map((movie) => (
            <ComboBox.Option value={movie.title} key={movie.id} matchRanges={movie.matchRanges} />
        ));
    };

    const footerMessage = () => {
        if (fullCount > options.length && !isLoading) {
            return _('%1 of %2 movies')
                .replace('%1', options.length.toString())
                .replace('%2', fullCount.toString());
        }
        return null;
    };

    const handleChange = (e, { value: comboBoxValue }) => {
        handleFetch(comboBoxValue);
    };

    useEffect(() => {
        handleFetch();

        return () => {
            stop();
        };
    }, [handleFetch, stop]);

    const comboBoxOptions = generateOptions();
    const footerMessageValue = footerMessage();

    return (
        <ComboBox
            value={value}
            controlledFilter
            inline
            placeholder={_('Select a movie...')}
            menuStyle={{ width: 300 }}
            onChange={handleChange}
            isLoadingOptions={isLoading}
            footerMessage={footerMessageValue}
        >
            {comboBoxOptions}
        </ComboBox>
    );
}

export default Fetching;

import React, { useCallback, useEffect, useState } from 'react';

import ComboBox from '@splunk/react-ui/ComboBox';
import useFetchOptions from '@splunk/react-ui/fixtures/useFetchOptions';
import { _ } from '@splunk/ui-utils/i18n';

const createFooterMessage = (loadingMore, count) => {
    return _('%1 movies %2').replace('%1', loadingMore).replace('%2', count);
};

function LoadMoreOnScrollBottom() {
    const [fullCount, setFullCount] = useState(0);
    const [isLoading, setIsLoading] = useState(false);
    const [isLoadingMore, setIsLoadingMore] = useState(false);
    const [options, setOptions] = useState([]);
    const [value, setValue] = useState('');

    /**
     * useFetchOptions mimics a real server by setting a timeout before returning new options. It
     * automatically tracks current indexes fetched and filtered options. Depending on how a server
     * is implemented, you would have more state values to track here such as indexes and list count.
     */
    const { fetch, fetchMore, getFullCount, stop } = useFetchOptions();

    const handleFetch = useCallback(
        (comboBoxValue = '') => {
            setValue(comboBoxValue);
            setIsLoading(true);

            fetch(comboBoxValue)
                .then((comboBoxOptions) => {
                    setOptions(comboBoxOptions);
                    setIsLoading(false);
                    setIsLoadingMore(false);
                    setFullCount(getFullCount());
                })
                .catch((error) => {
                    if (!error.isCanceled) {
                        throw error;
                    }
                });
        },
        [fetch, getFullCount, setOptions]
    );

    const handleFetchMore = (currentOptions) => {
        setIsLoadingMore(true);

        fetchMore(currentOptions)
            .then((comboBoxOptions) => {
                setOptions(comboBoxOptions);
                setIsLoadingMore(false);
                setIsLoadingMore(false);
                setFullCount(getFullCount());
            })
            .catch((error) => {
                if (!error.isCanceled) {
                    throw error;
                }
            });
    };

    const handleScrollBottom = () => {
        if (!isLoadingMore) {
            handleFetchMore(options);
        }
    };

    const generateOptions = () => {
        if (isLoading) {
            return null;
        }

        /*
         * Filtering is done server-side and the `matchRanges` prop would be either
         * be provided by the server, deduced based on the match algorithm, or omitted.
         */
        return options.map((movie) => (
            <ComboBox.Option value={movie.title} key={movie.id} matchRanges={movie.matchRanges} />
        ));
    };

    useEffect(() => {
        handleFetch();

        return () => {
            stop();
        };
    }, [setOptions, handleFetch, stop]);

    const handleChange = (e, { value: comboBoxValue }) => {
        handleFetch(comboBoxValue);
    };

    const footerMessage = createFooterMessage(
        fullCount.toString(),
        isLoadingMore ? _('(Loading more movies)') : ''
    );
    const comboBoxOptions = generateOptions();

    return (
        <ComboBox
            value={value}
            controlledFilter
            inline
            placeholder={_('Select a movie...')}
            menuStyle={{ width: 300 }}
            onChange={handleChange}
            onScrollBottom={
                // Disable when all items are loaded.
                fullCount === options.length ? undefined : handleScrollBottom
            }
            isLoadingOptions={isLoading}
            footerMessage={footerMessage}
        >
            {comboBoxOptions}
        </ComboBox>
    );
}

export default LoadMoreOnScrollBottom;
